import {
  Container,
  Typography,
  Grid,
  Card,
  CardContent,
  CardMedia,
  Button,
  Box,
  Chip,
  TextField,
  MenuItem,
  Skeleton,
} from "@mui/material";

import {
  Link,
} from "react-router-dom";

import {
  useEffect,
  useState,
} from "react";

import API from "../../services/api";


export default function Blog() {

  const [blogs, setBlogs] = useState([]);

  const [loading, setLoading] = useState(false);

  const [search, setSearch] =
    useState("");

  const [category, setCategory] =
    useState("");

  const [sort, setSort] =
    useState("newest");

  useEffect(() => {

    const fetchBlogs = async () => {

      try {

        setLoading(false);

        const response = await API.get(
          `/blogs?search=${search}&category=${category}&sort=${sort}`
        );

        setBlogs(response.data);

      } catch (error) {

        console.log(error);
      } finally {
        setLoading(false);
      }
    };

    fetchBlogs();

  }, [search, category, sort]);

  return (

    <Box>

      {/* HERO SECTION */}

      <Box
        sx={{
          minHeight: "60vh",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          textAlign: "center",
          px: 3,
          background:
            "linear-gradient(to right, #0f172a, #1e293b)",
          color: "white",
        }}
      >

        <Box>

          <Typography
            variant="h2"
            fontWeight={800}
            gutterBottom
          >
            Discover Stories,
            Ideas & Tech
          </Typography>

          <Typography
            variant="h6"
            sx={{
              maxWidth: 700,
              mx: "auto",
              opacity: 0.8,
              mb: 4,
            }}
          >
            Explore modern web
            development, programming,
            technology, and creative
            insights from developers.
          </Typography>

          <Button
            variant="contained"
            size="large"
            component={Link}
            to="/create-blog"
            sx={{
              px: 4,
              py: 1.5,
              borderRadius: 3,
              fontWeight: 700,
            }}
          >
            Start Writing
          </Button>

        </Box>

      </Box>
{loading && (

  <Grid container spacing={4}>

    {[1,2,3].map((item) => (

      <Grid item xs={12} md={4} key={item}>

        <Card
          sx={{
            borderRadius: 4,
          }}
        >

          <Skeleton
            variant="rectangular"
            height={240}
          />

          <CardContent>

            <Skeleton height={40} />

            <Skeleton height={20} />

            <Skeleton height={20} />

          </CardContent>

        </Card>

      </Grid>
    ))}
  </Grid>
)}
      {/* BLOG SECTION */}

      <Container sx={{ py: 8 }}>

        {/* TOP BAR */}

        <Box
          sx={{
            display: "flex",
            gap: 2,
            flexWrap: "wrap",
            mb: 5,
          }}
        >

          <TextField
            label="Search Blogs"
            value={search}
            onChange={(e) =>
              setSearch(e.target.value)
            }
            sx={{ flex: 1 }}
          />

          <TextField
            select
            label="Category"
            value={category}
            onChange={(e) =>
              setCategory(e.target.value)
            }
            sx={{ width: 200 }}
          >

            <MenuItem value="">
              All
            </MenuItem>

            <MenuItem value="Technology">
              Technology
            </MenuItem>

            <MenuItem value="Lifestyle">
              Lifestyle
            </MenuItem>

            <MenuItem value="General">
              General
            </MenuItem>

            <MenuItem value="Food">
              Food
            </MenuItem>

            <MenuItem value="Finance">
              Finance
            </MenuItem>

            <MenuItem value="Consult">
              Consult
            </MenuItem>

            <MenuItem value="Advice">
              Advice
            </MenuItem>

            <MenuItem value="Planning">
              Planning
            </MenuItem>

            <MenuItem value="Animals">
              Animals
            </MenuItem>

            <MenuItem value="Entertainment">
              Entertainment
            </MenuItem>

          </TextField>

          <TextField
            select
            label="Sort"
            value={sort}
            onChange={(e) =>
              setSort(e.target.value)
            }
            sx={{ width: 200 }}
          >

            <MenuItem value="newest">
              Newest
            </MenuItem>

            <MenuItem value="oldest">
              Oldest
            </MenuItem>

          </TextField>

        </Box>

        {/* HEADING */}

        <Typography
          variant="h4"
          fontWeight={700}
          gutterBottom
          sx={{ mb: 5 }}
        >
          Featured Blogs
        </Typography>

        {/* BLOG GRID */}

        <Grid container spacing={4}>

          {blogs.map((blog) => (

            <Grid
              item
              xs={12}
              sm={6}
              md={4}
              key={blog._id}
            >

              <Card
                sx={{
                  height: "100%",
                  borderRadius: 4,
                  overflow: "hidden",
                  transition:
                    "0.3s ease",
                  boxShadow: 3,

                  "&:hover": {
                    transform:
                      "translateY(-10px)",
                    boxShadow: 8,
                  },
                }}
              >

                <Box
                  sx={{
                    overflow: "hidden",
                  }}
                >

                  <CardMedia
                    component="img"
                    height="240"
                    image={blog.image}
                    alt={blog.title}
                    sx={{
                      transition:
                        "0.4s ease",

                      "&:hover": {
                        transform:
                          "scale(1.08)",
                      },
                    }}
                  />

                </Box>

                <CardContent
                  sx={{
                    p: 3,
                  }}
                >

                  <Chip
                    label={blog.category}
                    color="primary"
                    size="small"
                    sx={{ mb: 2 }}
                  />

                  <Typography
                    variant="h5"
                    fontWeight={700}
                    gutterBottom
                  >
                    {blog.title}
                  </Typography>

                  <Typography
                    variant="body2"
                    color="text.secondary"
                    sx={{
                      mb: 3,
                      lineHeight: 1.8,
                    }}
                  >
                    {blog.content.slice(
                      0,
                      120
                    )}...
                  </Typography>

                  <Button
                    component={Link}
                    to={`/blog/${blog._id}`}
                    variant="contained"
                    fullWidth
                    sx={{
                      borderRadius: 3,
                      py: 1.2,
                      fontWeight: 700,
                    }}
                  >
                    Read More
                  </Button>

                </CardContent>

              </Card>

            </Grid>
          ))}
        </Grid>

      </Container>

    </Box>
  );
}
